def fts_name(snapshot_id):
    if not re.fullmatch(r"N[0-9a-f]{64}", snapshot_id):
        raise ValueError("Invalid snapshot identifier")
    return "fts_" + snapshot_id[1:]

def page(self, snapshot, scope, rows, cursor=None, limit=100, key=lambda x: x["id"]):
    self.store.snapshot(snapshot)
    if not 1 <= limit <= 1000:
        raise ValueError("limit must be 1..1000")
    signature = sha(dump(scope))
    after = None
    if cursor:
        try:
            value = json.loads(base64.urlsafe_b64decode(cursor))
            if value["snapshot"] != snapshot or value["scope"] != signature:
                raise ValueError("Cursor scope/snapshot mismatch")
            after = value["after"]
        except Exception as exc:
            raise ValueError("Invalid cursor") from exc
    ordered = sorted(rows, key=key)
    total = len(ordered)
    selected = [r for r in ordered if after is None or key(r) > after]
    items = []
    used = 0
    for row in selected[:limit]:
        size = len(dump(row).encode())
        if used + size > 750000:
            if not items:
                raise ValueError("One result exceeds response budget; use bounded source/feature reads")
            break
        items.append(row)
        used += size
    nxt = (
        base64.urlsafe_b64encode(
            dump({"snapshot": snapshot, "scope": signature, "after": key(items[-1])}).encode()
        ).decode()
        if len(selected) > len(items)
        else None
    )
    manifest = self.store.manifest(snapshot)
    return dict(
        snapshot_id=snapshot,
        items=items,
        next_cursor=nxt,
        total=None if scope["kind"] == "inventory" and not manifest["inventory_complete"] else total,
        known_matches=total,
        remaining=max(0, len(selected) - len(items)),
        extraction_warnings={
            "count": sum(bool(d["warnings"]) for d in manifest["documents"]),
            "details": "inventory tool enumerates all document warnings without truncation",
        },
        scope=scope,
        inventory_complete=manifest["inventory_complete"],
    )

def _batches(segments, snapshot_id):
    batches, batch = [], []
    for segment in segments:
        if not segment["text"].strip():
            continue
        start = 0
        while start < len(segment["text"]):
            low, high = start + 1, len(segment["text"])
            best = None
            while low <= high:
                mid = (low + high) // 2
                unit = _unit(segment, start, mid)
                if _input_bytes(_payload([unit], snapshot_id)) <= MAX_INPUT_BYTES:
                    best, low = unit, mid + 1
                else:
                    high = mid - 1
            if best is None:
                raise ValueError("Original locator metadata cannot fit bounded input; no sources omitted")
            if batch and (
                len(batch) == MAX_UNITS
                or _input_bytes(_payload(batch + [best], snapshot_id)) > MAX_INPUT_BYTES
            ):
                batches.append(_payload(batch, snapshot_id))
                batch = []
            batch.append(best)
            start = best["end"]
    if batch:
        batches.append(_payload(batch, snapshot_id))
    return batches

def _sources(store, snapshot_id):
    manifest = store.manifest(snapshot_id)
    documents = {d["extraction_id"]: d for d in manifest["documents"]}
    rows = store.rows(
        "SELECT s.*, sd.document_version_id FROM segments s JOIN snapshot_documents sd "
        "ON s.extraction_id=sd.extraction_id WHERE sd.snapshot_id=? ORDER BY s.id",
        (snapshot_id,),
    )
    artifacts, segments = {}, []
    for row in rows:
        extraction = row["extraction_id"]
        if (
            extraction not in documents
            or documents[extraction]["document_version_id"] != row["document_version_id"]
        ):
            raise ValueError("Snapshot source membership mismatch")
        if extraction not in artifacts:
            artifact_sha = store.one("SELECT artifact_sha FROM extractions WHERE id=?", (extraction,))[
                "artifact_sha"
            ]
            artifacts[extraction] = (artifact_sha, json.loads(store.get(artifact_sha)))
        artifact_sha, artifact = artifacts[extraction]
        start, end, text = row["char_start"], row["char_end"], row["text"]
        if (
            not 0 <= start <= end <= len(artifact["text"])
            or artifact["text"][start:end] != text
            or sha(text) != row["text_sha"]
            or row["id"] != ident("S", extraction, row["ordinal"], start, end)
        ):
            raise ValueError("Immutable source text/range/identity mismatch")
        locators = [loc for loc in artifact["locators"] if loc["end"] >= start and loc["start"] <= end]
        if json.loads(row["locator_json"]) != locators:
            raise ValueError("Original locator mismatch")
        segments.append(
            {
                k: row[k]
                for k in (
                    "id",
                    "extraction_id",
                    "document_version_id",
                    "ordinal",
                    "text",
                    "text_sha",
                    "char_start",
                    "char_end",
                    "status",
                )
            }
            | dict(locators=locators, source_path=documents[extraction]["path"], artifact_sha=artifact_sha)
        )
    for extraction, document in documents.items():
        ranges = sorted((s for s in segments if s["extraction_id"] == extraction), key=lambda s: s["ordinal"])
        if not ranges:
            raise ValueError("Snapshot extraction has no immutable segment; source inventory gap")
        pos = 0
        for ordinal, segment in enumerate(ranges):
            if segment["ordinal"] != ordinal or segment["char_start"] != pos:
                raise ValueError("Immutable segment coverage gap or overlap")
            pos = segment["char_end"]
        if pos != len(artifacts[extraction][1]["text"]):
            raise ValueError("Immutable extraction tail gap")
    return dict(manifest=manifest, segments=segments)

def freeze_fts(store, snapshot_id):
    name = fts_name(snapshot_id)
    exists = store.db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (name,)).fetchone()
    if not exists:
        # Identifier is generated by this module from validated content-addressed IDs.
        store.db.execute(
            f"CREATE VIRTUAL TABLE {name} USING fts5(segment_id UNINDEXED,text,tokenize='unicode61 remove_diacritics 2')"
        )
        store.db.execute(
            f"""INSERT INTO {name} SELECT s.id,s.text FROM segments s JOIN snapshot_documents sd ON sd.extraction_id=s.extraction_id WHERE sd.snapshot_id=? ORDER BY s.id""",
            (snapshot_id,),
        )

def load_sources(store, snapshot):
    verified = _sources(store, snapshot)
    segments = {s["id"]: s for s in verified["segments"]}
    links = store.rows(
        """SELECT l.* FROM explicit_links l JOIN snapshot_links sl ON sl.link_id=l.id
                          WHERE sl.snapshot_id=? ORDER BY l.id""",
        (snapshot,),
    )
    return verified["manifest"], segments, links
